import { applyDiscount } from "./discount.mjs";

/** Invoice total in integer cents. */
export function invoiceTotal(lines, percentOff = 0) {
  const gross = lines.reduce((sum, line) => sum + line.unitCents * line.quantity, 0);
  return applyDiscount(gross, percentOff);
}

