import test from "node:test";
import assert from "node:assert/strict";
import { invoiceTotal } from "../src/invoice.mjs";

test("sums lines and applies the percentage discount", () => {
  const lines = [{ unitCents: 1000, quantity: 2 }, { unitCents: 500, quantity: 1 }];
  assert.equal(invoiceTotal(lines), 2500);
  assert.equal(invoiceTotal(lines, 10), 2250);
});

