import { appendFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";

const log = (line) => appendFileSync(".build-runs.log", `${line}\n`);
try {
  const config = JSON.parse(readFileSync("config/build.json", "utf8"));
  mkdirSync("out", { recursive: true });
  writeFileSync("out/bundle.txt", config.files.map((file) => readFileSync(file, "utf8")).join("\n"));
  log("OK");
} catch (error) {
  log(`FAIL ${error.code ?? error.name}`);
  console.error(`build failed: ${error.message}`);
  process.exitCode = 1;
}
